Given two sorted arrays a[] and b[], the task is to return union of both the arrays in sorted order. Union of two arrays is an array having all distinct elements that are present in either array. The input arrays may contain duplicates.Examples:Input: a[] = {1, 1, 2, 2, 2, 4}, b[] = {2, 2, 4, 4}Output: {1, 2, 4}Explanation: 1, 2 and 4 are the distinct elements present in either array.Input: a[] = {3, 5, 10, 10, 10, 15, 15, 20}, b[] = {5, 10, 10, 15, 30}Output: {3, 5, 10, 15, 20, 30}Explanation: 3, 5, 10, 15, 20 and 30 are the distinct elements present in either array.Try It YourselfTable of Content[Naive Approach] Using Nested Loops – O(n*m) Time and O(1) Space[Better Approach] Using Set – O((n+m)*(log (n+m))) Time and O(n+m) Space[Expected Approach] Using Merge Step of Merge Sort - O(n+m) Time and O(1) Space[Naive Approach] Using Nested Loops – O(n*m) Time and O(1) SpaceThe intuition behind this approach is to gather unique elements from two arrays by checking each element against the current result array. The idea is to traverse both the arrays and for each element, check if the element is present in the result or not. If not, then add this element to the result.
            C++

    // C++ program to find union of two sorted arrays 
// using nested loops

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<int> findUnion(vector<int>& a, vector<int>& b) {
    vector<int> res;

  	// Traverse through a[] and search every element
    // a[i] in result
  	for(int i = 0; i < a.size(); i++){

      	// check if the element is already 
        // in the result to avoid duplicates
        int j;
        for (j = 0; j < res.size(); j++) {
            if (res[j] == a[i]) 
                break;
        }
        if (j == res.size())
            res.push_back(a[i]);
  	}

  	// Traverse through b[] and search every element
    // b[i] in result
  	for(int i = 0; i < b.size(); i++){

      	// check if the element is already 
        // in the result to avoid duplicates
        int j;
        for (j = 0; j < res.size(); j++) {
            if (res[j] == b[i]) 
              break;
        }
        if (j == res.size())
            res.push_back(b[i]);
  	}

  	sort(res.begin(), res.end());
    return res;
}

int main() {
    vector<int> a = {1, 1, 2, 2, 2, 4};
    vector<int> b = {2, 2, 4, 4};

    vector<int> res = findUnion(a, b);

    for (int i = 0; i < res.size(); i++) 
        cout << res[i] << " ";

    return 0;
}


